import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format, parseISO, isWeekend, eachDayOfInterval } from 'date-fns';
import { addMonths, getDaysInMonth, startOfMonth, endOfMonth } from 'date-fns';

const computePayrollPeriod = (endDate) => {
  const end = parseISO(endDate);
  const payrollMonth = addMonths(end, 1);            // next month after endDate
  const payrollStart = startOfMonth(payrollMonth);
  const payrollEnd   = endOfMonth(payrollMonth);
  return {
    label: format(payrollStart, 'MMMM d') + '–' + format(payrollEnd, 'd, yyyy'),
  };
  // e.g. "June 1–30, 2026" or "July 1–31, 2026"
};

// ─── Add at the top of pdfGenerator.js ───────────────────────────────────────
// Paste your base64 strings here (without the "data:image/png;base64," prefix)
const HEADER_LOGO_BASE64 = ''; // your 3-logo strip or individual logos
const FOOTER_LOGO_LEFT_BASE64  = ''; // Bagong Pilipinas
const FOOTER_LOGO_RIGHT_BASE64 = ''; // TÜV Rheinland cert

// Folio page size: 8 × 13 inches in mm
const FOLIO_WIDTH_MM  = 203.2;
const FOLIO_HEIGHT_MM = 330.2;

// Fallback PH holidays (used when none are stored in settings)
const DEFAULT_PH_HOLIDAYS = [
 
];

// Reserved words that must never be treated as task names
const RESERVED_STATUS_WORDS = ['HOLIDAY', 'ABSENT', 'SATURDAY', 'SUNDAY', 'WEEKEND'];

// ─── Header ──────────────────────────────────────────────────────────────────

const addHeader = (doc, settings, userData, dateRange) => {
  const pageWidth = doc.internal.pageSize.getWidth();

  // 1. 3-in-1 Header Logo Strip (Left Side) - Base boundary fixed at Y = 10
  doc.addImage(HEADER_LOGO_BASE64, 'JPEG', 10, 10, 80, 26); 

  // 2. Agency Text Block Starting Coordinate
  const textStartX = 95; 

  // --- Moved higher up and tightly grouped vertically ---
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('Republic of the Philippines', textStartX, 11, { align: 'left' }); // Moved up to 11

  doc.setFont('helvetica', 'bold');
  doc.text(
    settings?.departmentName || 'QUEZON CITY HEALTH DEPARTMENT',
    textStartX, 16, { align: 'left' } // Kept tight gap (11 + 5)
  );

  doc.setFont('helvetica', 'normal');
  doc.text('Quezon City, Metro Manila', textStartX, 21, { align: 'left' }); 
  
  doc.setFontSize(8); 
  doc.text(
    'QC Hall Compound, Mayaman St., corner Kalayaan Ave., Gate 4, Quezon City',
    textStartX, 26, { align: 'left' }
  );
  doc.text('Tel No. 8988-42-42 loc 1607', textStartX, 31, { align: 'left' });
  doc.text('Email: cityhealth@quezoncity.gov.ph', textStartX, 36, { align: 'left' });

 

  // 3. Report Titles (Centered) - Shifted up slightly to balance the extra space
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text('Accomplishment Report', pageWidth / 2, 58, { align: 'center' });

  const startFmt = format(parseISO(dateRange.startDate), 'MMMM dd');
  const endFmt   = format(parseISO(dateRange.endDate),   'MMMM dd, yyyy');
  doc.setFontSize(11);
  doc.setFont('helvetica', 'normal');
  doc.text(`Attendance Period: ${startFmt} to ${endFmt}`, pageWidth / 2, 65, { align: 'center' });

  const { label } = computePayrollPeriod(dateRange.endDate);
  const payrollLine = `Payroll Period: ${label}`;
  doc.setFont('helvetica', 'bold');
  doc.text(payrollLine, pageWidth / 2, 72, { align: 'center' });

  // Underline for Payroll Period
  const pw = doc.getTextWidth(payrollLine);
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.line(pageWidth / 2 - pw / 2, 73.5, pageWidth / 2 + pw / 2, 73.5);
};

// ─── Footer ──────────────────────────────────────────────────────────────────

const addFooter = (doc, userData, settings, pageNumber, totalPages) => {
  const pageWidth  = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  // ── Submitted by / Noted by ───────────────────────────────────────────────
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text('Submitted by:', 20, pageHeight - 70);

  doc.setFont('helvetica', 'bold');
  doc.text(userData?.fullname?.toUpperCase() || 'EMPLOYEE NAME', 20, pageHeight - 55);
  doc.setFont('helvetica', 'normal');
  doc.text(userData?.position || 'Data Controller', 20, pageHeight - 50);

  const supervisor = settings?.signatories?.supervisor;
  if (supervisor?.name) {
    doc.text('Noted by:', pageWidth - 90, pageHeight - 70);
    doc.setFont('helvetica', 'bold');
    doc.text(supervisor.name, pageWidth - 90, pageHeight - 55);
    doc.setFont('helvetica', 'normal');
    if (supervisor.title)    doc.text(supervisor.title,    pageWidth - 90, pageHeight - 50);
    if (supervisor.division) doc.text(supervisor.division, pageWidth - 90, pageHeight - 47);
  }

  // ── Motto ─────────────────────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic', 'bold');
  doc.setFontSize(11);
  doc.text('"Matatag, Mapagkakatiwalaan, at Maaasahang Pamunuan"', 20, pageHeight - 10);

  // ── Footer logos ──────────────────────────────────────────────────────────
  // Left logo (Bagong Pilipinas) — adjust x/y/w/h to taste
  doc.addImage(FOOTER_LOGO_LEFT_BASE64,  'PNG', pageWidth - 75, pageHeight - 25, 22, 20);
  // Right logo (TÜV cert) — adjust x/y/w/h to taste
  doc.addImage(FOOTER_LOGO_RIGHT_BASE64, 'PNG', pageWidth - 50, pageHeight - 25, 40, 20);

  // ── Page number REMOVED (delete or comment out) ───────────────────────────
  // doc.text(`Page ${pageNumber} of ${totalPages}`, pageWidth / 2, pageHeight - 5, { align: 'center' });
};

// ─── Calendar builder ─────────────────────────────────────────────────────────

/**
 * Build groups of consecutive same-task working days.
 * Accepts a holidayDates array (string[]) so holidays can be set dynamically.
 */
const buildMergedCalendar = (reports, startDate, endDate, holidayDates = []) => {
  const holidaySet = new Set(
    holidayDates.length > 0 ? holidayDates : DEFAULT_PH_HOLIDAYS
  );
  const checkHoliday = (dateStr) => holidaySet.has(dateStr);

  const start = parseISO(startDate);
  const end   = parseISO(endDate);
  const days  = eachDayOfInterval({ start, end });

  const dayMap = {};
  days.forEach(day => {
    const dateStr = format(day, 'yyyy-MM-dd');
    dayMap[dateStr] = {
      date:      dateStr,
      dayNum:    format(day, 'd'),
      month:     format(day, 'MMMM'),
      dayName:   format(day, 'EEEE'),
      isWeekend: isWeekend(day),
      isHoliday: checkHoliday(dateStr),
      tasks:     {},
      totalCount: 0,
    };
  });

  // Fill tasks — skip reserved words and non-work days
  reports.forEach(report => {
    const day = dayMap[report.reportDate];
    if (!day) return;
    if (day.isWeekend || day.isHoliday) return;
    if (RESERVED_STATUS_WORDS.includes(report.task?.toUpperCase?.().trim())) return;

    if (!day.tasks[report.task]) day.tasks[report.task] = 0;
    day.tasks[report.task] += Number(report.count);
    day.totalCount += Number(report.count);
  });

  const sortedDays = Object.values(dayMap).sort((a, b) => a.date.localeCompare(b.date));

  const getSignature = (tasks) =>
    JSON.stringify(Object.entries(tasks).sort((a, b) => a[0].localeCompare(b[0])));

  const groups = [];
  let currentGroup = null;

  for (const day of sortedDays) {
    const isNonWork = day.isWeekend || day.isHoliday;
    const isAbsent  = !isNonWork && day.totalCount === 0;

    if (isNonWork || isAbsent) {
      if (currentGroup) { groups.push(currentGroup); currentGroup = null; }
      groups.push({
        type: day.isWeekend ? 'WEEKEND' : day.isHoliday ? 'HOLIDAY' : 'ABSENT',
        days: [day],
      });
      continue;
    }

    const signature = getSignature(day.tasks);
    if (currentGroup && currentGroup.signature === signature) {
      currentGroup.days.push(day);
    } else {
      if (currentGroup) groups.push(currentGroup);
      currentGroup = { type: 'TASK', signature, days: [day] };
    }
  }
  if (currentGroup) groups.push(currentGroup);

  // Pre-compute merged totals per TASK group
  groups.forEach(group => {
    if (group.type !== 'TASK') return;
    group.mergedTasks = {};
    group.days.forEach(day => {
      Object.entries(day.tasks).forEach(([task, count]) => {
        group.mergedTasks[task] = (group.mergedTasks[task] || 0) + count;
      });
    });
  });

  return groups;
};

// ─── Table row builder ────────────────────────────────────────────────────────

/**
 * 3-column layout:
 *   col 0 – date number   (narrow, centered)
 *   col 1 – status label  (narrow, centered) – blank for work days
 *   col 2 – task bullets  (auto width, centered vertically)
 *
 * Header: "Date" colSpan 2  |  "TASK ACCOMPLISHED"
 * Consecutive same-task days share one task cell via rowSpan.
 */
const buildTableRows = (groups) => {
  const rows = [];
  let currentMonth = '';

  const makeDateCell = (day) => {
    let label;
    if (day.month !== currentMonth) {
      currentMonth = day.month;
      label = `${day.month} ${day.dayNum}`;
    } else {
      label = day.dayNum;
    }
    return { content: label, styles: { halign: 'center', valign: 'middle' } };
  };

  groups.forEach(group => {
    if (group.type === 'TASK') {
      const dayCount = group.days.length;
      const bullets  = Object.entries(group.mergedTasks)
        .map(([task, count]) => `• ${count} ${task}`)
        .join('\n');

      group.days.forEach((day, idx) => {
        const dc = makeDateCell(day);
        if (idx === 0) {
          rows.push([
            dc,
            { content: '', styles: { halign: 'center', valign: 'middle' } },
            {
              content: bullets,
              styles:  { valign: 'middle', halign: 'left' },   // ← vertically centered
              ...(dayCount > 1 ? { rowSpan: dayCount } : {}),
            },
          ]);
        } else {
          // Spanned rows — only 2 cells; task cell is merged from first row
          rows.push([
            dc,
            { content: '', styles: { halign: 'center', valign: 'middle' } },
          ]);
        }
      });
    } else {
      group.days.forEach(day => {
        let status = '';
        if (group.type === 'WEEKEND') status = day.dayName.toUpperCase();
        else if (group.type === 'HOLIDAY') status = 'HOLIDAY';
        else if (group.type === 'ABSENT')  status = 'ABSENT';

        rows.push([
          makeDateCell(day),
          { content: status, styles: { halign: 'center', valign: 'middle' } },
          { content: '',     styles: {} },
        ]);
      });
    }
  });

  return rows;
};

// ─── Main export ──────────────────────────────────────────────────────────────

/**
 * @param {Array}  reports      – raw daily report documents
 * @param {Object} userData     – logged-in user data
 * @param {Object} dateRange    – { startDate, endDate } in 'yyyy-MM-dd'
 * @param {Object} settings     – Firestore settings doc:
 *                                  .departmentName, .signatories, .holidays[]
 */
export const generateAccomplishmentPDF = async (reports, userData, dateRange, settings = {}) => {
  try {
    // Folio: 8 × 13 inches
    const doc = new jsPDF('p', 'mm', [FOLIO_WIDTH_MM, FOLIO_HEIGHT_MM]);

    addHeader(doc, settings, userData, dateRange);

    // Dynamic holidays: stored as array of 'yyyy-MM-dd' strings in settings
    const holidayDates = Array.isArray(settings?.holidays)
      ? settings.holidays.map(h => (typeof h === 'string' ? h : h.date))
      : [];

    const groups    = buildMergedCalendar(reports, dateRange.startDate, dateRange.endDate, holidayDates);
    const tableBody = buildTableRows(groups);

    autoTable(doc, {
      startY: 78,

      head: [[
        {
          content: 'Date',
          colSpan: 2,
          styles: { halign: 'center', valign: 'middle', fontStyle: 'bold', fontSize: 10 },
        },
        {
          content: 'TASK ACCOMPLISHED',
          styles: { halign: 'center', valign: 'middle', fontStyle: 'bold', fontSize: 10 },
        },
      ]],

      body: tableBody,
      theme: 'grid',

      headStyles: {
        fillColor: [255, 255, 255],
        textColor: [0, 0, 0],
        lineColor: [0, 0, 0],
        lineWidth: 0.5,
      },

      styles: {
        fontSize:    7,
        // ← smaller row height: tight padding matching the sample
        cellPadding: { top: 1.2, right: 3, bottom: 1.2, left: 3 },
        lineColor:   [0, 0, 0],
        lineWidth:   0.2,
        textColor:   [0, 0, 0],
        overflow:    'linebreak',
      },

      columnStyles: {
        0: { cellWidth: 26, halign: 'center', valign: 'middle' },
        1: { cellWidth: 28, halign: 'center', valign: 'middle' },
        2: { cellWidth: 'auto', halign: 'left', valign: 'middle' }, // ← vertically centered
      },

      didDrawPage: (data) => {
        if (data.pageNumber > 1) {
          addHeader(doc, settings, userData, dateRange);
        }
      },
    });

    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      addFooter(doc, userData, settings, i, totalPages);
    }

    const safeName = (userData?.fullname || 'Report')
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9_]/g, '');
    doc.save(`${safeName}_${format(new Date(), 'yyyyMMdd')}.pdf`);

    return true;
  } catch (error) {
    console.error('PDF Generation Error:', error);
    throw error;
  }
};